using System.Text.Json.Nodes;

// The implicit schema: every order has a decimal "total"
static decimal Revenue(IEnumerable<JsonObject> orders) =>
    orders.Sum(o => (decimal?)o["total"] ?? 0m); // v2 orders add 0

using System.Text.Json.Nodes;

// One place that knows every shape an order has ever had
static decimal Total(JsonObject order) => (int?)order["schemaVersion"] switch
{
    null or 1 => (decimal)order["total"]!,
    2 => (decimal)order["totalAmount"]!,
    var v => throw new NotSupportedException($"Unknown order schema v{v}")
};

static decimal Revenue(IEnumerable<JsonObject> orders) => orders.Sum(Total);

