db.runCommand({
  collMod: "orders",
  validator: {
    $jsonSchema: {
      bsonType: "object",
      required: ["customer", "total"],
      properties: {
        total: { bsonType: ["double", "decimal"] }
      }
    }
  },
  validationLevel: "moderate"
});
